INSERT INTO exercise_translations (exercise_id, locale, name, instructions, warmup_cues, execution_steps, attention_cues, source, updated_at) VALUES
  ('ex_goblet_squat', 'nl', 'Goblet Squat', 'Houd een dumbbell verticaal tegen je borst. Zak door je heupen en knieën tot je dijen parallel zijn aan de grond, duw daarna door je hielen omhoog.', 'Warm 5 minuten op met lichte cardio en beweeg je heupen en enkels.', '["Ga staan met voeten op schouderbreedte","Houd de dumbbell tegen je borst","Zak gecontroleerd naar beneden","Duw door je hielen omhoog"]', '["Houd je rug recht","Knieën volgen je tenen"],', 'human', datetime('now')),
  ('ex_goblet_squat', 'fr', 'Goblet Squat', 'Tenez un haltère verticalement contre votre poitrine. Descendez en fléchissant hanches et genoux jusqu’à ce que les cuisses soient parallèles au sol, puis poussez via les talons pour remonter.', 'Échauffez-vous 5 minutes avec du cardio léger et mobilisez hanches et chevilles.', '["Debout, pieds à largeur d’épaules","Haltère contre la poitrine","Descendez de façon contrôlée","Poussez via les talons pour remonter"]', '["Gardez le dos droit","Les genoux suivent la direction des orteils"],', 'human', datetime('now')),
  ('ex_goblet_squat', 'de', 'Goblet Squat', 'Halte eine Hantel vertikal vor deiner Brust. Gehe über Hüften und Knie nach unten, bis die Oberschenkel parallel zum Boden sind, und drücke über die Fersen wieder nach oben.', 'Wärme 5 Minuten mit leichtem Cardio auf und mobilisiere Hüfte und Sprunggelenke.', '["Steh breiter als schulterbreit","Halt die Hantel vor der Brust","Kontrolliert nach unten","Über die Fersen nach oben drücken"]', '["Halte den Rücken gerade","Die Knie folgen den Zehen"],', 'human', datetime('now')),
  ('ex_bench_press', 'nl', 'Bankdrukken', 'Lig op de bank, voeten stevig op de grond. Laat de stang gecontroleerd naar je borst zakken en druk hem terug tot je armen bijna gestrekt zijn.', 'Doe 2 opwarmsets met licht gewicht en rol je schouders naar achteren.', '["Lig stevig op de bank","Laat de stang naar je borst zakken","Druk omhoog tot armen bijna gestrekt"]', '["Laat iemand meekijken als je zwaar gaat","Polsen recht onder de stang"],', 'human', datetime('now')),
  ('ex_push_up', 'nl', 'Push-Up', 'Plaats je handen iets breder dan schouderbreedte. Laat je lichaam gecontroleerd zakken tot je borst bijna de grond raakt en duw jezelf terug omhoog.', 'Warm je polsen en schouders op met cirkels en een lichte variant.', '["Handen iets breder dan je schouders","Lichaam in één rechte lijn","Zak tot borst bijna de grond raakt","Duw terug omhoog"]', '["Houd je core aangespannen","Laat je heupen niet zakken"],', 'human', datetime('now')),
  ('ex_plank', 'fr', 'Plank', 'Placez-vous sur les avant-bras et les orteils, le corps formant une ligne droite. Contractez abdominaux et fessiers et maintenez la position.', 'Respirez normalement et vérifiez l’alignement avant de commencer.', '["Sur les avant-bras et les orteils","Corps aligné","Abdominaux contractés"]', '["Ne cambrez pas le bas du dos","Épaules au-dessus des coudes"],', 'human', datetime('now')),
  ('ex_lat_pulldown', 'de', 'Lat-Zug', 'Zieh die Stange kontrolliert zur oberen Brust und lass sie langsam wieder zurück. Zieh die Schulterblätter nach unten und hinten.', 'Leichte Schultermobility und ein Aufwärmsatz.', '["Griff etwas breiter als Schulterbreite","Zur oberen Brust ziehen","Langsam zurückführen"]', '["Nicht in die Stange reinhängen","Rumpf stabil halten"],', 'human', datetime('now'));